// Verus solution for forming a plural with the simplified rule.
//
// Rule:
// - if the word ends with 's', append "es"
// - otherwise append "s"
//
// Input assumptions:
// - non-empty
// - all chars are lowercase 'a'..'z'

use vstd::prelude::*;

verus! {

spec fn is_lowercase(c: char) -> bool {
    'a' <= c && c <= 'z'
}

fn solve(s: &Vec<char>) -> (result: Vec<char>)
    requires
        s.len() > 0,
        forall|i: int| 0 <= i < s.len() ==> is_lowercase(s[i]),
    ensures
        // Result is original followed by the right suffix.
        if s[s.len() - 1] == 's' {
            result@ == s@ + seq!['e', 's']
        } else {
            result@ == s@ + seq!['s']
        },
{
    let mut result: Vec<char> = Vec::new();

    // Copy input into result.
    let mut i: usize = 0;
    while i < s.len()
        invariant
            i <= s.len(),
            result@ == s@.subrange(0, i as int),
    {
        result.push(s[i]);
        i += 1;
    }

    // Append suffix according to rule.
    if s[s.len() - 1] == 's' {
        result.push('e');
        result.push('s');

        // Help the verifier connect pushes to the final sequence expression.
        assert(result@ == s@ + seq!['e', 's']);
    } else {
        result.push('s');
        assert(result@ == s@ + seq!['s']);
    }

    result
}

} // verus!